 public const string Scene="Assets/TruckCornhole/Scenes/TruckCornhole.unity";const string Root="Assets/TruckCornhole/";
 static Material Mat(string name,Color color,float gloss=.3f){string path=Root+"Materials/"+name+".mat";var m=AssetDatabase.LoadAssetAtPath<Material>(path);if(m==null){m=new Material(Shader.Find("Universal Render Pipeline/Lit"));AssetDatabase.CreateAsset(m,path);}m.color=color;m.SetFloat("_Smoothness",gloss);m.enableInstancing=true;return m;}
 static PhysicsMaterial Contact(string name,float friction,float bounce){string path=Root+"Materials/"+name+".asset";var m=AssetDatabase.LoadAssetAtPath<PhysicsMaterial>(path);if(m==null){m=new PhysicsMaterial(name);AssetDatabase.CreateAsset(m,path);}m.dynamicFriction=m.staticFriction=friction;m.bounciness=bounce;m.frictionCombine=PhysicsMaterialCombine.Average;m.bounceCombine=PhysicsMaterialCombine.Minimum;return m;}
 static GameObject Box(string name,Transform parent,Vector3 position,Vector3 size,Material mat,CornholeCourse c=null,CornholeSurfaceKind kind=CornholeSurfaceKind.Barrier,PhysicsMaterial contact=null){var g=GameObject.CreatePrimitive(PrimitiveType.Cube);g.name=name;g.transform.SetParent(parent,false);g.transform.localPosition=position;g.transform.localScale=size;g.GetComponent<Renderer>().sharedMaterial=mat;if(name=="Course isolation wall")g.GetComponent<Renderer>().enabled=false;if(c==null)UnityEngine.Object.DestroyImmediate(g.GetComponent<Collider>());else{g.GetComponent<Collider>().sharedMaterial=contact;var surface=g.AddComponent<CornholeSurface>();surface.kind=kind;surface.course=c;}return g;}
 [MenuItem("Truck Sports/Create Cornhole and Integrate Collection")]
 public static void Create(){foreach(var folder in new[]{"Scenes","Materials","Audio"})Directory.CreateDirectory(Root+folder);AssetDatabase.Refresh();var scene=EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);var root=new GameObject("Truck Cornhole authority");var m=root.AddComponent<CornholeMatch>();m.settings=root.AddComponent<SportsSettings>();m.feedback=root.AddComponent<SportsFeedback>();m.feedback.settings=m.settings;m.feedback.clips=Audio();m.feedback.voices=8;SportsUIAuthoring.Events(root);root.AddComponent<AudioListener>();m.courses=new CornholeCourse[4];
  var wood=Mat("Maple board",new Color(.72f,.44f,.19f),.42f);var ramp=Mat("Ramp graphite",new Color(.09f,.14f,.19f));var dark=Mat("Rubber",new Color(.02f,.035f,.05f));var teal=Mat("Trampoline teal",new Color(.03f,.68f,.63f),.6f);var white=Mat("Reference cream",new Color(.95f,.9f,.72f));var ground=Mat("Arena ground",new Color(.07f,.16f,.13f));var contact=Contact("Truck board contact",.38f,.14f);var rampPhysics=Contact("Approach contact",.65f,0);var padPhysics=Contact("Trampoline contact",.1f,0);
  var sun=new GameObject("Cornhole sunlight").AddComponent<Light>();sun.type=LightType.Directional;sun.intensity=2.2f;sun.shadows=LightShadows.Soft;sun.transform.rotation=Quaternion.Euler(48,-30,0);RenderSettings.ambientMode=UnityEngine.Rendering.AmbientMode.Flat;RenderSettings.ambientLight=new Color(.5f,.58f,.65f);RenderSettings.fog=false;
  for(int i=0;i<4;i++){var g=new GameObject("Isolated Cornhole course "+(i+1));g.transform.position=new Vector3(i*110,0,0);var c=g.AddComponent<CornholeCourse>();m.courses[i]=c;c.match=m;c.index=i;c.center=i*110;c.replay=g.AddComponent<CornholeReplay>();c.replay.course=c;
   var approach=Box("Descending launch ramp",g.transform,new Vector3(0,3.64f,-11),new Vector3(7,.6f,24),ramp,c,CornholeSurfaceKind.Approach,rampPhysics);approach.transform.localRotation=Quaternion.Euler(13.5f,0,0);
   for(int z=0;z<4;z++){float zz=-19+z*5;float y=1.30f-zz*Mathf.Tan(13.5f*Mathf.Deg2Rad);var stripe=Box("Entry reference "+z,g.transform,new Vector3(0,y,zz),new Vector3(6.7f,.02f,.13f),white);stripe.transform.localRotation=approach.transform.localRotation;}
   Box("Trampoline platform",g.transform,new Vector3(0,.22f,2.4f),new Vector3(7.6f,.35f,4.6f),dark,c,CornholeSurfaceKind.Trampoline,padPhysics);
   // Compression is a child visual; it never changes the launch collision surface.
   var frame=new GameObject("Trampoline compression presentation");frame.transform.SetParent(g.transform,false);frame.transform.localPosition=new Vector3(0,.45f,2.4f);c.trampoline=frame.transform;Box("Spring bed",frame.transform,Vector3.zero,new Vector3(6.9f,.18f,3.8f),teal);for(int side=-1;side<=1;side+=2){Box("Trampoline side frame",g.transform,new Vector3(side*3.65f,.5f,2.4f),new Vector3(.24f,.32f,4.6f),white);for(int z=0;z<8;z++)Box("Visible spring",frame.transform,new Vector3(side*3.45f,-.1f,-1.5f+z*.43f),new Vector3(.25f,.14f,.08f),white);}
   Box("Trampoline approach arrow",g.transform,new Vector3(0,.58f,1.4f),new Vector3(.13f,.02f,1.2f),white);
   Box("Catch ground",g.transform,new Vector3(0,-10.5f,36),new Vector3(54,1,170),ground,c,CornholeSurfaceKind.Ground,rampPhysics);for(int side=-1;side<=1;side+=2)Box("Course isolation wall",g.transform,new Vector3(side*27,12,35),new Vector3(.5f,45,170),dark,c,CornholeSurfaceKind.Barrier,contact);
   var board=new GameObject("Inclined open target board");board.transform.SetParent(g.transform,false);board.transform.localPosition=new Vector3(0,3.6f,64);board.transform.localRotation=Quaternion.Euler(-10,0,0);board.AddComponent<MeshFilter>().sharedMesh=BoardMesh();board.AddComponent<MeshRenderer>().sharedMaterial=wood;var mesh=board.AddComponent<MeshCollider>();mesh.sharedMesh=board.GetComponent<MeshFilter>().sharedMesh;mesh.sharedMaterial=contact;var surface=board.AddComponent<CornholeSurface>();surface.course=c;surface.kind=CornholeSurfaceKind.Board;c.board=board.transform;
   var line=new GameObject("Hole rim marking").AddComponent<LineRenderer>();line.transform.SetParent(board.transform,false);line.useWorldSpace=false;line.sharedMaterial=teal;line.positionCount=65;line.startWidth=line.endWidth=.10f;for(int a=0;a<65;a++){float angle=a*Mathf.PI*2/64;line.SetPosition(a,new Vector3(Mathf.Cos(angle)*1.7f,.025f,6+Mathf.Sin(angle)*1.7f));}for(int side=-1;side<=1;side+=2){Box("Board edge stripe",board.transform,new Vector3(side*6.8f,.012f,0),new Vector3(.16f,.018f,23.8f),white);Box("Board leg",g.transform,new Vector3(side*5.6f,-2,72),new Vector3(.5f,12,.5f),dark);}
   var label=new GameObject("Target course label").AddComponent<TextMeshPro>();label.transform.SetParent(board.transform,false);label.transform.localPosition=new Vector3(0,.035f,-8);label.transform.localRotation=Quaternion.Euler(90,0,0);label.font=TMP_Settings.defaultFontAsset;label.fontSize=5;label.text="TRUCK CORNHOLE\nCOURSE "+(i+1);label.alignment=TextAlignmentOptions.Center;label.rectTransform.sizeDelta=new Vector2(12,3);label.color=new Color(.1f,.14f,.15f);
   c.launchEffect=Effect(g.transform,new Vector3(0,.7f,2.4f),teal);c.holeEffect=Effect(g.transform,c.board.localPosition+Vector3.forward*6+Vector3.up*2,white);
   c.trucks=new CornholeTruck[4];for(int t=0;t<4;t++)c.trucks[t]=Truck(c,t,contact,dark);
   var camera=new GameObject("Driver seat and replay view "+(i+1));camera.transform.position=c.StartPosition+new Vector3(0,4,-8);var cam=camera.AddComponent<Camera>();cam.fieldOfView=72;cam.nearClipPlane=.015f;cam.farClipPlane=180;cam.backgroundColor=new Color(.23f,.4f,.52f);cam.clearFlags=CameraClearFlags.SolidColor;c.chase=camera.AddComponent<CornholeCamera>();c.chase.course=c;c.chase.view=cam;Cab(c,dark,white);IsolateRendering(c);
