 // Render-only layers are scene-local component settings. Collider layers and host TagManager stay untouched.
 static void IsolateRendering(CornholeCourse course){int layer=24+course.index;foreach(var renderer in course.GetComponentsInChildren<Renderer>(true)){var filter=renderer.GetComponent<MeshFilter>();if(renderer is MeshRenderer&&filter!=null&&renderer.GetComponent<Collider>()!=null){var visual=new GameObject(renderer.name+" visible surface",typeof(MeshFilter),typeof(MeshRenderer));visual.transform.SetParent(renderer.transform,false);visual.layer=layer;visual.GetComponent<MeshFilter>().sharedMesh=filter.sharedMesh;visual.GetComponent<MeshRenderer>().sharedMaterials=renderer.sharedMaterials;visual.GetComponent<MeshRenderer>().enabled=renderer.enabled;UnityEngine.Object.DestroyImmediate(renderer);UnityEngine.Object.DestroyImmediate(filter);}else renderer.gameObject.layer=layer;}foreach(var truck in course.trucks)foreach(var renderer in truck.GetComponentsInChildren<Renderer>(true))renderer.gameObject.layer=layer;course.chase.view.cullingMask=1<<layer;}
 static Mesh BoardMesh(){string path=Root+"Materials/Open board mesh.asset";var existing=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(existing!=null)return existing;var vertices=new List<Vector3>();var triangles=new List<int>();const int n=96;for(int i=0;i<n;i++){float a=i*Mathf.PI*2/n,dx=Mathf.Cos(a),dz=Mathf.Sin(a);float distance=Mathf.Min(7/Mathf.Max(.00001f,Mathf.Abs(dx)),(dz>0?6:18)/Mathf.Max(.00001f,Mathf.Abs(dz)));for(int layer=0;layer<2;layer++){float y=layer==0?0:-.35f;vertices.Add(new Vector3(dx*1.65f,y,6+dz*1.65f));vertices.Add(new Vector3(dx*distance,y,6+dz*distance));}}
  for(int i=0;i<n;i++){int a=i*4,b=(i+1)%n*4;triangles.AddRange(new[]{a,b,a+1,a+1,b,b+1,a+2,a+3,b+2,a+3,b+3,b+2,a,a+2,b,b,a+2,b+2,a+1,b+1,a+3,a+3,b+1,b+3});}var mesh=new Mesh{name="Solid inclined board with real circular opening"};mesh.SetVertices(vertices);mesh.SetTriangles(triangles,0);mesh.RecalculateNormals();mesh.RecalculateBounds();AssetDatabase.CreateAsset(mesh,path);return mesh;
 }
 static CornholeTruck Truck(CornholeCourse c,int number,PhysicsMaterial contact,Material tire){var g=new GameObject("Delivery truck "+(number+1));var body=g.AddComponent<Rigidbody>();body.mass=12;body.centerOfMass=new Vector3(0,-.02f,0);body.interpolation=RigidbodyInterpolation.Interpolate;body.collisionDetectionMode=CollisionDetectionMode.ContinuousDynamic;body.solverIterations=12;body.solverVelocityIterations=4;body.angularDamping=.13f;body.maxDepenetrationVelocity=3;var box=g.AddComponent<BoxCollider>();box.size=new Vector3(.7f,.36f,1.2f);box.center=new Vector3(0,.14f,0);box.sharedMaterial=contact;var t=g.AddComponent<CornholeTruck>();t.course=c;t.body=body;t.shape=box;var visual=HockeyAuthoring.TruckGeometry(g.transform,1.25f);t.paint=visual.GetComponentsInChildren<MeshRenderer>().First(r=>r.name=="Cab");var friction=AssetDatabase.LoadAssetAtPath<FrictionPreset>("Assets/NWH/WheelController/Resources/Wheel Controller 3D/Defaults/DefaultFrictionPreset.asset");t.wheels=new WheelController[4];g.layer=2;for(int i=0;i<4;i++){var wgo=new GameObject("NWH approach wheel "+i);wgo.layer=2;wgo.transform.SetParent(g.transform,false);wgo.transform.localPosition=new Vector3(i%2==0?-.3f:.3f,.02f,i<2?.43f:-.43f);var w=wgo.AddComponent<WheelController>();w.wheel.radius=.15f;w.wheel.width=.1f;w.wheel.mass=.6f;w.spring.maxLength=.06f;w.spring.maxForce=80;w.damper.bumpRate=w.damper.reboundRate=180;w.rollingResistanceTorque=.015f;w.FrictionPreset=friction;w.frictionSubsteps=10;w.forceApplicationPointDistance=.035f;w.layerMask=1;t.wheels[i]=w;var wheel=GameObject.CreatePrimitive(PrimitiveType.Cylinder);wheel.name="Rubber tire";wheel.transform.SetParent(visual.transform,false);wheel.transform.localPosition=new Vector3(i%2==0?-.3f:.3f,0,i<2?.43f:-.43f);wheel.transform.localRotation=Quaternion.Euler(0,0,90);wheel.transform.localScale=new Vector3(.3f,.055f,.3f);wheel.GetComponent<Renderer>().sharedMaterial=tire;UnityEngine.Object.DestroyImmediate(wheel.GetComponent<Collider>());}
  t.engine=Loop(g,"Assets/NWH/Vehicle Physics 2/Sound/Engine/Running/EngineRunning - Truck4.wav");t.scrape=Loop(g,"Assets/NWH/Vehicle Physics 2/Sound/GroundNoise/AsphaltSkidNoise.wav");t.wind=Loop(g,Root+"Audio/Wind.wav");g.transform.position=c.StartPosition;g.SetActive(false);return t;
 }
 static void Cab(CornholeCourse course,Material dark,Material trim){var inside=new GameObject("Driver seat interior");inside.transform.SetParent(course.chase.transform,false);inside.layer=24+course.index;
  Box("Dashboard",inside.transform,new Vector3(0,-.27f,.47f),new Vector3(.82f,.12f,.32f),dark);Box("Hood",inside.transform,new Vector3(0,-.31f,.75f),new Vector3(.75f,.09f,.35f),trim);for(int sign=-1;sign<=1;sign+=2){Box("Windscreen pillar",inside.transform,new Vector3(sign*.42f,.05f,.48f),new Vector3(.035f,.72f,.04f),dark).transform.localRotation=Quaternion.Euler(0,0,-sign*6);Box("Door trim",inside.transform,new Vector3(sign*.48f,-.21f,.12f),new Vector3(.09f,.14f,.8f),dark);}Box("Roof",inside.transform,new Vector3(0,.43f,.45f),new Vector3(.95f,.07f,.4f),dark);for(int i=0;i<3;i++)Box("Dash gauge",inside.transform,new Vector3(-.2f+i*.15f,-.20f,.39f),new Vector3(.07f,.035f,.018f),trim);var wheel=new GameObject("Driver steering wheel").AddComponent<LineRenderer>();wheel.transform.SetParent(inside.transform,false);wheel.useWorldSpace=false;wheel.sharedMaterial=dark;wheel.startWidth=wheel.endWidth=.012f;wheel.positionCount=33;for(int a=0;a<=32;a++){float angle=a*Mathf.PI*2/32;wheel.SetPosition(a,new Vector3(-.17f+Mathf.Cos(angle)*.11f,-.20f+Mathf.Sin(angle)*.075f,.22f));}course.chase.interior=inside.GetComponentsInChildren<Renderer>();foreach(var r in course.chase.interior)r.gameObject.layer=24+course.index;
 }
 static AudioSource Loop(GameObject g,string path){var s=g.AddComponent<AudioSource>();s.clip=AssetDatabase.LoadAssetAtPath<AudioClip>(path);s.loop=true;s.playOnAwake=false;s.spatialBlend=0;return s;}
 static ParticleSystem Effect(Transform parent,Vector3 pos,Material material){var g=new GameObject("Pooled launch / hole burst");g.transform.SetParent(parent,false);g.transform.localPosition=pos;var p=g.AddComponent<ParticleSystem>();var main=p.main;main.playOnAwake=false;main.loop=false;main.duration=.5f;main.startLifetime=.65f;main.startSpeed=4;main.startSize=.18f;main.startColor=material.color;main.maxParticles=32;var emission=p.emission;emission.rateOverTime=0;emission.SetBursts(new[]{new ParticleSystem.Burst(0,24)});p.GetComponent<ParticleSystemRenderer>().sharedMaterial=material;p.Stop(true,ParticleSystemStopBehavior.StopEmittingAndClear);return p;}
 static AudioClip[] Audio(){string[] names={"Launch","Hole","Result","Wind"};for(int k=0;k<4;k++){string path=Root+"Audio/"+names[k]+".wav";int rate=22050,length=rate*(k==3?2:1);var random=new System.Random(44);using(var writer=new BinaryWriter(File.Create(path))){writer.Write(System.Text.Encoding.ASCII.GetBytes("RIFF"));writer.Write(36+length*2);writer.Write(System.Text.Encoding.ASCII.GetBytes("WAVEfmt "));writer.Write(16);writer.Write((short)1);writer.Write((short)1);writer.Write(rate);writer.Write(rate*2);writer.Write((short)2);writer.Write((short)16);writer.Write(System.Text.Encoding.ASCII.GetBytes("data"));writer.Write(length*2);for(int i=0;i<length;i++){double time=(double)i/rate,fade=k==3?Math.Min(1,time*10)*Math.Min(1,(2-time)*10):Math.Exp(-time*5);double sample=k==3?(random.NextDouble()*2-1)*.16:(Math.Sin(time*(k==0?180+time*300:k==1?660:440)*Math.PI*2)+.25*Math.Sin(time*990*Math.PI*2))*.3;writer.Write((short)(sample*fade*short.MaxValue));}}AssetDatabase.ImportAsset(path,ImportAssetOptions.ForceSynchronousImport);}
  return new[]{AssetDatabase.LoadAssetAtPath<AudioClip>("Assets/Heat - Complete Modern UI/Audio/Click.wav"),AssetDatabase.LoadAssetAtPath<AudioClip>("Assets/TruckBowling/Audio/Truck pin.wav"),AssetDatabase.LoadAssetAtPath<AudioClip>(Root+"Audio/Launch.wav"),AssetDatabase.LoadAssetAtPath<AudioClip>(Root+"Audio/Hole.wav"),AssetDatabase.LoadAssetAtPath<AudioClip>(Root+"Audio/Result.wav")};
 }
