 public static void UpgradeFront(){var scene=EditorSceneManager.OpenScene(SportsBuilder.FrontScene);var f=UnityEngine.Object.FindAnyObjectByType<SportsFrontEnd>();var page=f.pages[1].transform;var corn=page.Find("CORNHOLE Sport Card");if(corn==null){corn=UnityEngine.Object.Instantiate(page.Find("HOCKEY Sport Card").gameObject,page).transform;corn.name="CORNHOLE Sport Card";var icon=corn.Find("Rink icon");if(icon!=null)UnityEngine.Object.DestroyImmediate(icon.gameObject);SportsUIAuthoring.Button(page,"CORNHOLE","cornhole",Vector2.zero,new Vector2(390,58));}
  string[] labels={"BILLIARDS","HOCKEY","BOWLING","AIR HOCKEY","WALLBALL","CORNHOLE"};string[] actions={"billiards","hockey","bowling","airhockey","wallball","cornhole"};for(int i=0;i<6;i++){float x=(i%3-1)*455,y=i<3?115:-175;var card=page.Find(labels[i]+" Sport Card");var r=card.GetComponent<RectTransform>();r.sizeDelta=new Vector2(430,267);r.anchoredPosition=new Vector2(x,y);var title=card.Find("Sport").GetComponent<TMP_Text>();title.text=i==1?"ICE HOCKEY":labels[i];title.rectTransform.anchoredPosition=new Vector2(0,99);title.rectTransform.sizeDelta=new Vector2(400,50);title.fontSizeMax=32;title.fontSizeMin=26;var desc=card.Find("Description").GetComponent<TMP_Text>();desc.rectTransform.anchoredPosition=new Vector2(0,25);desc.rectTransform.sizeDelta=new Vector2(395,90);desc.fontSizeMax=21;desc.fontSizeMin=18;if(i==5)desc.text="The truck IS the bag.\nRamp → trampoline → board.\n1–4 simultaneous · Five rounds.";foreach(var child in card.GetComponentsInChildren<RectTransform>(true))if(child.name.Contains("icon"))child.gameObject.SetActive(false);foreach(var a in page.GetComponentsInChildren<SportsMenuAction>(true))if(a.action==actions[i]||i==0&&a.action=="practice"){var button=a.GetComponent<RectTransform>();button.sizeDelta=new Vector2(i==0?195:390,53);button.anchoredPosition=new Vector2(x+(i==0?(a.action=="practice"?100:-100):0),y-90);a.button.normalTextObj.rectTransform.sizeDelta=button.sizeDelta-new Vector2(10,6);a.button.normalTextObj.fontSizeMax=22;if(i==0){a.button.buttonText=a.action=="practice"?"PRACTICE":"MATCH";a.button.normalTextObj.text=a.button.buttonText;}}}
  f.pages[0].transform.Find("Collection").GetComponent<TMP_Text>().text="BILLIARDS · ICE HOCKEY · BOWLING\nAIR HOCKEY · WALLBALL · CORNHOLE";page.Find("Subtitle").GetComponent<TMP_Text>().text="Six sports · Local play · Your truck is the game";var help=f.pages[2].transform.Find("Guidance").GetComponent<TMP_Text>();if(!help.text.Contains("CORNHOLE"))help.text+="\n\nCORNHOLE\nThe truck IS the bag: ramp, trampoline, then land on or through the board. 1–4 simultaneous courses, driver-seat view and multi-angle replays. Full rules in Cornhole help.";help.fontSizeMax=20;help.fontSizeMin=17;EditorSceneManager.SaveScene(scene);AssetDatabase.SaveAssets();Debug.Log("CORNHOLE_FRONT_INTEGRATED");
 }
 public static void PreserveFrontBuild(){LWS.TruckWallball.Editor.WallballAuthoring.UpgradeFront();var front=UnityEngine.Object.FindAnyObjectByType<SportsFrontEnd>();foreach(var key in new[]{"billiards","hockey","bowling","airhockey","wallball","cornhole"})if(!front.pages[1].GetComponentsInChildren<SportsMenuAction>(true).Any(a=>a.action==key))throw new Exception("Legacy regeneration lost sport "+key);Debug.Log("CORNHOLE_LEGACY_FRONT_PRESERVED");SportsBuilder.Build();}
 public static void CreateBuild(){Create();SportsBuilder.Build();}
 public static void Validate(){CornholeFixtures.Run();var scene=EditorSceneManager.OpenScene(Scene);var m=UnityEngine.Object.FindAnyObjectByType<CornholeMatch>();if(m==null||m.courses.Length!=4||m.menus.names.Length!=4||m.feedback.clips.Any(x=>x==null))throw new Exception("Cornhole references incomplete");foreach(var root in scene.GetRootGameObjects())foreach(var t in root.GetComponentsInChildren<Transform>(true))if(GameObjectUtility.GetMonoBehavioursWithMissingScriptCount(t.gameObject)>0)throw new Exception("Missing Cornhole script: "+t.name);if(UnityEngine.Object.FindObjectsByType<AudioListener>(FindObjectsInactive.Include).Length!=1||UnityEngine.Object.FindObjectsByType<UnityEngine.EventSystems.EventSystem>(FindObjectsInactive.Include).Length!=1)throw new Exception("Cornhole listener/EventSystem invalid");foreach(var c in m.courses){if(c.replay==null||c.chase.interior==null||c.chase.interior.Length<8||c.chase.view.nearClipPlane>.02f)throw new Exception("Cornhole cab/replay references incomplete");foreach(var truck in c.trucks){if(Vector3.Distance(truck.paint.bounds.center,truck.body.position)>1.5f)throw new Exception("Cornhole visual offset from body: "+c.index);}if(c.trucks.Length!=4||c.board.GetComponent<MeshCollider>().convex||c.trucks.Any(t=>t.wheels.Length!=4||t.wind.clip==null))throw new Exception("Course collision/pool incomplete");var point=c.board.TransformPoint(new Vector3(0,2,c.holeZ));if(Physics.Raycast(point,-c.board.up,out var hit,4)&&hit.collider==c.board.GetComponent<Collider>())throw new Exception("Hole is blocked");}Debug.Log("CORNHOLE_SAVED_SCENE_VALIDATED");}
}
